import {fitBoard} from './fit-board.mjs';
import {markingInfo,markingCard,bandColors,surfaceMark} from './component-markings.mjs';
import {roundedHousing} from './realistic-finish.mjs';
import {buildUnderside} from './library-traces.mjs';
import * as THREE from './vendor/three.module.js';
import {OrbitControls} from './vendor/OrbitControls.js';
import {circuitSvg} from './circuit-library.mjs';
import {familyPalette,familyLegend} from './component-colors.mjs';
// Coordinates deliberately match the accompanying principle diagram; not a manufacturing layout.
export function circuitParts(kind){const r=(x,y,v,name='R')=>({type:'R',x,y,v,name}),c=(x,y,v,name='C')=>({type:'C',x,y,v,name}),ic=(x,y,name='IC',w=55,h=40)=>({type:'IC',x,y,name,w,h}),d=(x,y,v,name='D')=>({type:'D',x,y,v,name});
 const common={divider:[r(240,133,true,'R1'),r(240,239,true,'R2')],sensor:[r(240,133,true,'R1'),r(240,239,true,'Sensor resistivo')],pullup:[r(290,116,true)],pulldown:[r(290,205,true)],led:[r(180,110,false,'R1'),d(300,180,true,'LED')],lowpass:[r(200,125,false),c(340,203,true)],highpass:[c(200,125,false),r(340,203,true)],decoupling:[c(230,199,true),ic(410,150,'IC',90,85)],mosfet:[{type:'LOAD',x:350,y:121,v:true,name:'Carga'},r(180,212,false,'Rg'),ic(329,212,'NMOS',32,36)],relay:[{type:'L',x:350,y:121,v:true,name:'Bobina del relé'},r(180,212,false,'Rb'),ic(329,212,'NPN',32,36),d(465,121,true)],shunt:[{type:'LOAD',x:280,y:123,v:true,name:'Carga'},r(280,223,true,'Rshunt')],buck:[{type:'L',x:310,y:107,v:false,name:'L',span:80},c(400,197,true),d(230,138,true)],ldo:[c(150,196,true,'Cin'),c(450,196,true,'Cout'),ic(300,120,'LDO',75,36)],charge:[ic(315,160,'Cargador',115,90),ic(122,272,'Batería',75,25)],buffer:[ic(325,170,'OP AMP',48,52)],noninv:[ic(325,170,'OP AMP',48,52),r(328,278,false,'Rf'),r(120,278,false,'Rg')],inv:[ic(325,170,'OP AMP',48,52),r(160,205,false,'Rin'),r(340,277,false,'Rf')],comparator:[ic(325,170,'COMP',48,52),r(465,110,true,'Rpu')]};const values={divider:{R1:'10K',R2:'10K'},led:{R1:'1K'},lowpass:{R:'10K',C:'100 nF'},highpass:{R:'10K',C:'100 nF'},noninv:{Rf:'10K',Rg:'10K'},inv:{Rin:'10K',Rf:'20K'},shunt:{Rshunt:'0R1'}};return (common[kind]||[]).map(p=>({...p,value:values[kind]?.[p.name]||'',package:p.type==='R'?'AXIAL':p.type==='C'?'CERAMIC-DISC':'DIDACTIC'}));}
export function circuitThumbnail(kind){const parts=circuitParts(kind);let s=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 380" role="img" aria-label="Montaje didáctico en perspectiva"><rect width="640" height="380" fill="#081723"/><g transform="translate(87 24) matrix(.85 .10 -.22 .72 0 0)"><rect x="0" y="15" width="600" height="340" rx="16" fill="#12613d"/>${circuitSvg(kind).replaceAll('#0c1e2c','#075136').replaceAll('#172f41','#12613d').replaceAll('#73d4ee','#e9a566').replace('<svg ','<svg x="0" y="0" width="600" height="340" ')} `;
 for(const p of parts){const w=p.w||(p.v?23:43),h=p.h||(p.v?43:23),z=p.type==='C'?20:p.type==='L'?18:10,col=familyPalette[p.type]||'#526c7d',x=p.x-w/2,y=p.y-h/2;s+=`<path d="M${x} ${y}v${-z}h${w}v${h}l0 ${z}Z" fill="${col}" stroke="#07121c" stroke-width="2"/><rect x="${x}" y="${y-z}" width="${w}" height="${h}" rx="4" fill="${col}" stroke="#d0edff" stroke-width="1"/>`;if(p.type==='L')s+=`<ellipse cx="${p.x}" cy="${p.y-z}" rx="${w*.34}" ry="${h*.33}" fill="none" stroke="#f6ca78" stroke-width="5"/>`;}
 return s+'</g><text x="28" y="357" fill="#b4c9d7" font-family="sans-serif" font-size="13">3D didáctico · abrir para girar y acercar</text></svg>';}
export function buildCircuitBodies(kind){const group=new THREE.Group();const silver=new THREE.MeshStandardMaterial({color:'#d4dee6',metalness:.85,roughness:.25});
 const mesh=(geom,mat,g=group)=>{const o=new THREE.Mesh(geom,mat);o.castShadow=true;o.receiveShadow=true;g.add(o);return o;};
 const cyl=(a,b,rad,mat,g=group)=>{const v=new THREE.Vector3(...b).sub(new THREE.Vector3(...a)),o=mesh(new THREE.CylinderGeometry(rad,rad,v.length(),20),mat,g);o.position.copy(new THREE.Vector3(...a).add(new THREE.Vector3(...b)).multiplyScalar(.5));o.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),v.normalize());return o;};
 for(const p of circuitParts(kind)){const g=new THREE.Group();g.position.set((p.x-300)/10,(170-p.y)/10,.3);g.rotation.z=p.v?Math.PI/2:0;g.userData.part=p;group.add(g);const mat=new THREE.MeshStandardMaterial({color:familyPalette[p.type]||'#354454',roughness:.35,metalness:.12});
 if(['R','C','L','D','LOAD'].includes(p.type)){const span=(p.span||56)/20;for(const x of [-span,span]){cyl([x,0,0],[x,0,1.3],.1,silver,g);cyl([x,0,1.3],[Math.sign(x)*1.7,0,1.3],.1,silver,g);const pad=mesh(new THREE.CylinderGeometry(.35,.35,.12,20),new THREE.MeshStandardMaterial({color:'#dfb668',metalness:.8,roughness:.3}),g);pad.rotation.x=Math.PI/2;pad.position.set(x,0,.04);}
 if(p.type==='R'){cyl([-1.7,0,1.3],[1.7,0,1.3],.66,mat,g);const bands=markingInfo(p).bands||[];bands.forEach((color,i)=>{const x=-1.3+i*(bands.length===5?.53:.7)+(i===bands.length-1?.2:0);const stripe=cyl([x,0,1.3],[x+.19,0,1.3],.68,new THREE.MeshBasicMaterial({color:bandColors[color],toneMapped:false}),g);stripe.userData.preserveMarking=true;});}
 else if(p.type==='C'){const body=mesh(roundedHousing(THREE,3.4,1.45,2.7),mat,g);body.position.z=1.65;const top=mesh(new THREE.BoxGeometry(2.9,1.49,.13),new THREE.MeshStandardMaterial({color:'#9be7ff'}),g);top.position.z=2.9;surfaceMark(THREE,g,markingInfo(p).bodyText,2.5,.9,0,0,3.01);}
 else if(p.type==='L'){const ring=mesh(new THREE.TorusGeometry(1.08,.46,16,40),mat,g);ring.position.z=1.5;for(let i=0;i<14;i++){const a=i*Math.PI*2/14,coil=mesh(new THREE.TorusGeometry(.51,.09,8,16),new THREE.MeshStandardMaterial({color:'#e8b365',metalness:.75,roughness:.24}),g);coil.position.set(Math.cos(a)*1.08,Math.sin(a)*1.08,1.5);coil.rotation.set(Math.PI/2,a,0);}}
 else{cyl([-1.5,0,1.3],[1.5,0,1.3],.65,mat,g);if(p.type==='D')cyl([.9,0,1.3],[1.13,0,1.3],.66,silver,g);}}
 else{const w=p.w/10,h=p.h/10,body=mesh(roundedHousing(THREE,w,h,1.6),mat,g);body.position.z=1;for(const side of [-1,1])for(let i=0;i<4;i++){const pin=mesh(new THREE.BoxGeometry(.6,.25,.2),silver,g);pin.position.set(side*(w/2+.2),(i-1.5)*h/5,.35);}}
 g.traverse(o=>{if(o.isMesh)o.userData.part=p;});}
 return group;}
let renderer=null,scene,camera,controls,host,observer,frame=0,boardRoot=null,token=0;
function disposeRoot(){if(!boardRoot)return;const mats=new Set(),geos=new Set();boardRoot.traverse(o=>{if(o.geometry)geos.add(o.geometry);if(o.material)mats.add(o.material);});for(const m of mats){m.map?.dispose();m.dispose();}for(const g of geos)g.dispose();scene.remove(boardRoot);boardRoot=null;}
export function closeLibrary3D(){token++;globalThis.cancelAnimationFrame?.(frame);observer?.disconnect();controls?.dispose();disposeRoot();if(renderer)renderer.domElement.remove();host=null;}
export function mountLibrary3D(container,kind){closeLibrary3D();host=container;const mine=token;container.innerHTML=`<div class="library3dStage" id="library3dStage"></div><div class="library3dTools"><button id="library3dFlip">↻ Voltear placa</button><button id="library3dBottom">◎ Inferior</button><button id="library3dHome">↶ Centrar</button><button id="library3dTop">◎ Superior</button><button id="library3dZoomIn" aria-label="Acercar modelo">＋</button><button id="library3dZoomOut" aria-label="Alejar modelo">−</button><label><input id="library3dBodies" type="checkbox" checked> Mostrar componentes</label></div><p id="library3dFace" class="libraryFace">Cara superior · componentes</p><div id="library3dNets" class="libraryTraceNets"></div><div class="familyLegend">${familyLegend}</div><div id="libraryMarking"></div><p id="library3dInfo">Arrastra para girar · Pellizca para acercar · Toca un componente para identificarlo.</p><small>Montaje conceptual sobre el esquema. Colores de cuerpo educativos. Las bandas codifican el valor indicado; si falta la tolerancia, se usa ±5 % como ejemplo identificado en la ficha. Cara inferior: pistas didácticas de las conexiones representadas en el esquema. Los terminales externos y las alimentaciones omitidas en el esquema no se añaden. No es un diseño de PCB fabricable ni un pinout comercial.</small>`;
 const $=id=>document.getElementById(id),stage=$('library3dStage');try{if(renderer?.getContext().isContextLost()){renderer.dispose();renderer=null;}renderer ||= new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(globalThis.devicePixelRatio||1,2));renderer.setClearColor('#081723');renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.NeutralToneMapping;renderer.toneMappingExposure=1.0;stage.append(renderer.domElement);renderer.domElement.onwebglcontextlost=e=>{e.preventDefault();$('library3dInfo').textContent='Motor 3D pausado. Cierra esta ficha y vuelve a abrirla para recuperarlo.';};scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(40,1,.1,500);camera.up.set(0,0,1);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.minDistance=20;controls.maxDistance=190;controls.maxPolarAngle=Math.PI;scene.add(new THREE.HemisphereLight('#ffffff','#263d32',.7));const light=new THREE.DirectionalLight('#ffffff',2);light.position.set(-20,-25,70);light.castShadow=true;light.shadow.mapSize.set(1024,1024);Object.assign(light.shadow.camera,{left:-40,right:40,top:40,bottom:-40,near:1,far:160});light.shadow.normalBias=.03;light.shadow.bias=-.0002;scene.add(light);const rim=new THREE.DirectionalLight('#ffffff',1.0);rim.position.set(30,20,-30);scene.add(rim);
 boardRoot=new THREE.Group();scene.add(boardRoot);const pcb=new THREE.Mesh(new THREE.BoxGeometry(60,34,1),new THREE.MeshStandardMaterial({color:'#12613d',roughness:.6}));pcb.position.z=-.55;boardRoot.add(pcb);const bodies=buildCircuitBodies(kind);boardRoot.add(bodies);const underside=buildUnderside(kind,THREE);boardRoot.add(underside.root);
 const chooseNet=name=>{underside.select(name);$('library3dInfo').textContent=name?'Red '+name+' · sigue la pista iluminada y sus terminales. Voltea para relacionarla con el componente.':'Todas las conexiones de la cara inferior en cobre.';$('library3dNets').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.net===name));};
 $('library3dNets').innerHTML='<span>Seguir por debajo</span><button data-net="">Todas</button>'+underside.nets.map(n=>'<button data-net="'+n.name+'">'+n.name+'</button>').join('');$('library3dNets').querySelectorAll('button').forEach(b=>b.onclick=()=>{chooseNet(b.dataset.net);if(camera.position.z>=0){camera.position.z=-Math.max(30,camera.position.z);controls.update();}});
 controls.addEventListener('change',()=>{$('library3dFace').textContent=camera.position.z<0?'Cara inferior · pistas y terminales':'Cara superior · componentes';});
 const image=new Image();image.onload=()=>{if(token!==mine)return;const texture=new THREE.Texture(image);texture.colorSpace=THREE.SRGBColorSpace;texture.needsUpdate=true;texture.anisotropy=renderer.capabilities.getMaxAnisotropy();const plane=new THREE.Mesh(new THREE.PlaneGeometry(60,34),new THREE.MeshPhysicalMaterial({map:texture,roughness:.78,clearcoat:.05,metalness:0}));plane.receiveShadow=true;plane.position.z=.02;boardRoot.add(plane);};image.onerror=()=>{if(token===mine)$('library3dInfo').textContent='No se ha cargado el plano de conexiones. Consulta el esquema 2D inferior.';};image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(circuitSvg(kind).replaceAll('#0c1e2c','#075136').replaceAll('#172f41','#12613d').replaceAll('#73d4ee','#e9a566').replaceAll('#081723','#075136').replaceAll('#0b1e2c','#075136').replaceAll('#cfaa59','#e9a566'));
 const home=()=>fitBoard(THREE,camera,controls,[-30,-17,30,17],{bottom:camera.position.z<0,height:5});observer=new ResizeObserver(()=>{const w=stage.clientWidth,h=stage.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();home();});observer.observe(stage);home();$('library3dHome').onclick=home;$('library3dFlip').onclick=()=>{camera.position.z=(camera.position.z<0?1:-1)*Math.max(30,Math.abs(camera.position.z));controls.update();};$('library3dBottom').onclick=()=>{fitBoard(THREE,camera,controls,[-30,-17,30,17],{bottom:true,top:true,height:5});};$('library3dTop').onclick=()=>{fitBoard(THREE,camera,controls,[-30,-17,30,17],{top:true,height:5});};$('library3dZoomIn').onclick=()=>{camera.position.sub(controls.target).multiplyScalar(.8).add(controls.target);controls.update();};$('library3dZoomOut').onclick=()=>{camera.position.sub(controls.target).multiplyScalar(1.25).add(controls.target);controls.update();};$('library3dBodies').onchange=e=>bodies.visible=e.target.checked;
 let down;renderer.domElement.onpointerdown=e=>down=[e.clientX,e.clientY];renderer.domElement.onpointerup=e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>8)return;const rect=renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,1-(e.clientY-rect.top)/rect.height*2),camera);if(camera.position.z<0){ray.params.Line.threshold=.35;const found=ray.intersectObjects(underside.pickables,true)[0];if(found)chooseNet(found.object.userData.net);return;}if(!bodies.visible)return;const hit=ray.intersectObjects(bodies.children,true)[0];if(hit){const p=hit.object.userData.part;$('libraryMarking').innerHTML=markingCard(p);$('library3dInfo').textContent=p.name+' · '+({R:'Resistencia · naranja',C:'Condensador / capacitor · azul',L:'Bobina / inductor · violeta',IC:'Bloque funcional',D:'Diodo',LOAD:'Carga'}[p.type]);}};
 const render=()=>{frame=requestAnimationFrame(render);if(!host?.isConnected)return;controls.update();renderer.render(scene,camera);};render();
 }catch(e){stage.innerHTML='<p class="threeFallback">El navegador no ha iniciado WebGL. Puedes ver la ilustración en perspectiva y el esquema 2D.</p>'+circuitThumbnail(kind);}}
